// 数据源名称
var db = '数据源名称';

// 获取当前用户
Creater = GetCurrentUser();

// 设置初始密码
var PassWord = '123456';

// 获取部门信息、技能级别、岗位名称、员工手机号、线体、班组信息、员工姓名、员工工号、当前日期时间
var Department = dept.GetCurrentText();
var groupName = '生产管理';
if (Department === '' || Department === '请选择') {
    ShowMessage({
        'message': '请选择部门',
        type: 'warning'
    });
}
switch (Department) {
    case '总装车间':
        groupName = '现场操作';
        break;
    case '网络信息部':
        groupName = '开发运维';
        break;
    case '生产部门':
        groupName = '生产管理';
        break;
    case '其他用户':
        groupName = '其他用户';
        break;
    default:
}

var Skill_Level = Skill_Level.GetCurrentText();
var Position = pos.Text;
var Phone = phone.Value;
var line_code = line_code.GetCurrentText();
var work_shift = work_shift.GetCurrentText();
if (work_shift === '' || work_shift === '请选择') {
    ShowMessage({
        'message': '请选择班组',
        type: 'warning'
    });
}
var Name = name.Text;
if (Name === '') {
    ShowMessage({
        'message': '名字不能为空，请填写姓名',
        type: 'warning'
    });
}
var JobNumber = GH.Text;
if (JobNumber === '') {
    ShowMessage({
        'message': '工号不能为空，请填写工号',
        type: 'warning'
    });
}

var DATE = new Date().format('yyyy-MM-dd hh:mm:ss');
var flag = 1;
var sql1 = `SELECT user_code FROM your_sensitive_table_name`; // 敏感表名
var options = {
    text: '正在添加用户，请稍后',
    background: 'rgba(0,0,0,0.8)'
};
var loadingRes = ShowLoading(options); // 获取返回值
SQLExecute1(db, 0, sql1, function(res1) {
    setTimeout(() => {
        loadingRes();
        var data1 = res1.data.records;
        if (data1.length !== 0) {
            for (let i = 0; i < data1.length; i++) {
                if (JobNumber === data1[i].user_code) {
                    flag = 0;
                    break;
                }
            }
        }
        if (flag) {
            if (Name === '' || JobNumber == '请选择') {
                ShowMessage({
                    'message': '名字和工号不能为空，请输入完整信息',
                    type: 'warning'
                });
            } else {
                var user = {
                    "userName": `${JobNumber}`,
                    "password": `${PassWord}`,
                    "groupName": `${groupName}`, //`业务操作`, //开发运维，现场操作
                    "description": `${Department}` + '-' + `${Position}`,
                    "nickName": `${Name}`,
                    "extendField": {
                        "work_shift": `${work_shift}`,
                        "Department": `${Department}`,
                    }
                };
                var adduser = user_add(user); //添加用户
                console.log(adduser);
                if (200 === adduser.status || adduser.msg === '名字或租户ID重复') {
                    var sql = `INSERT INTO your_sensitive_table_name (user_id,Department_name,user_code,Position_name,Phone,user_name,CreatDate,user_Password,Creater,Enabled, work_shift,g_xb,Skill_Level)
                                VALUES (uuid(),'${Department}','${JobNumber}','${Position}','${Phone}','${Name}','${DATE}','${PassWord}','${Creater}',1,'${work_shift}','${line_code}','${Skill_Level}')`; // 替换敏感表名
                    SQLExecute1(db, 1, sql, function(res) {
                        if (res.errorCode === 0) {
                            $System.$PicManager.用户管理.$Variable.reGetdata = false;
                            ShowMessage({
                                'message': '新增成功',
                                type: 'success'
                            });
                            ClosePage("用户新增");
                            flag = 1;
                        } else {
                            ShowMessage({
                                'message': '新增失败',
                                type: 'error'
                            });
                            ClosePage("用户新增");
                            flag = 1;
                        }
                    });
                } else {
                    ShowMessage({
                        'message': `${adduser.msg}`,
                        type: 'error'
                    });
                }
            }
        } else {
            ShowMessage({
                'message': '用户名重复',
                type: 'warning'
            });
        }
    }, 5000);
});

