let sql = `SELECT distinct Department FROM your_sensitive_table_name`; // 选择唯一的部门名称
SQLExecute1('tbeasql', 0, sql, function(res) {
    if (0 === res.errorCode) {
        let resData = res.data.records;
        let comboboxData = [];
        if (resData) {
            for (let i = 0; i < resData.length; i++) {
                comboboxData.push({
                    value: resData[i].Department,
                    text: resData[i].Department,
                });
            }
        }
        // 将部门信息填充到部门下拉框中
        $(dept.id).combobox({
            value: '请选择',
            valueField: 'value',
            textField: 'text',
            data: comboboxData
        });
    }
});

